// Reset state independently of the production handlers, including render cache.
static void reset(uint32_t color = RGBW32(120,80,40,77), uint8_t brightness = 100) {
  strip = Strip{};
  strip.getMainSegment().colors[0] = color;
  strip.getMainSegment().mode = 50;
  Segment::renderedColor = color;
  bri = brightness;
  effectCurrent = 50;
  colPri[0] = R(color); colPri[1] = G(color); colPri[2] = B(color); colPri[3] = W(color);
  stateUpdates = colorUpdates = publishes = colorWrites = brightnessWrites = modeWrites = 0;
}

