// STOP must leave both light state and publication/update hooks untouched.
static void expectStop(const char* label) {
  expectColor(RGBW32(120,80,40,77), label);
  check(bri == 100 && effectCurrent == 50 && strip.getMainSegment().cct == 127, label);
  check(colPri[0] == 120 && colPri[1] == 80 && colPri[2] == 40 && colPri[3] == 77, label);
  check(stateUpdates == 0 && colorUpdates == 0 && publishes == 0 && colorWrites == 0 &&
        brightnessWrites == 0 && modeWrites == 0, label);
}

// Fixed reference vectors catch the normalization error independently of RGB->HSV.
static void testHsvBoundaries(KnxIpUsermod& mod) {
  struct Vector { float h, s, v; uint8_t r, g, b; };
  const Vector vectors[] = {
    {0,0,0,0,0,0}, {120,1,0,0,0,0}, {0,0,1,255,255,255},
    {35,0,0.5f,128,128,128}, {0,1,1,255,0,0}, {60,1,1,255,255,0},
    {120,1,1,0,255,0}, {180,1,1,0,255,255}, {240,1,1,0,0,255},
    {300,1,1,255,0,255}, {360,1,1,255,0,0}, {-60,1,1,255,0,255},
    {720,1,1,255,0,0}, {0,0.5f,0.5f,128,64,64}, {120,1,1.f/255,0,1,0}
  };
  for (const auto& v : vectors) {
    uint8_t r,g,b;
    mod.hsvToRgb(v.h,v.s,v.v,r,g,b);
    check(r == v.r && g == v.g && b == v.b, "HSV converter reference vector");
    reset();
    mod.applyHSV(v.h,v.s,v.v,true);
    expectColor(RGBW32(v.r,v.g,v.b,77), "applyHSV reference vector and white preservation");
    check(colPri[0] == v.r && colPri[1] == v.g && colPri[2] == v.b && colPri[3] == 77,
          "applyHSV updates GUI color");
    check(stateUpdates == 1 && colorUpdates == 0 && publishes == 1, "HSV publication hooks");
  }
  reset(); mod.applyHSV(0,1,1,false);
  expectColor(RGBW32(255,0,0,0), "explicit white reset");
}

// Exhaustively check all 24-bit RGB inputs, including byte-encoded HSV feedback.
static void testPrecision(KnxIpUsermod& mod) {
  unsigned maxFloatError = 0, maxWireError = 0;
  for (unsigned color = 0; color < 0x1000000; ++color) {
    uint8_t r=R(color), g=G(color), b=B(color), rr,gg,bb;
    float h,s,v;
    mod.rgbToHsv(r,g,b,h,s,v);
    mod.hsvToRgb(h,s,v,rr,gg,bb);
    unsigned error = std::max({std::abs(int(rr)-r),std::abs(int(gg)-g),std::abs(int(bb)-b)});
    maxFloatError = std::max(maxFloatError,error);
    mod.hsvToRgb(mod.byteToHueDeg(mod.hueDegToByte(h)), mod.byteToPct01(mod.pct01ToByte(s)),
                 mod.byteToPct01(mod.pct01ToByte(v)), rr,gg,bb);
    error = std::max({std::abs(int(rr)-r),std::abs(int(gg)-g),std::abs(int(bb)-b)});
    maxWireError = std::max(maxWireError,error);
  }
  std::printf("RGB round trips: 16777216, max channel error float=%u, KNX HSV bytes=%u\n", maxFloatError,maxWireError);
  check(maxFloatError == 0, "float HSV round-trip precision");
  check(maxWireError <= 4, "byte HSV quantization bound");
}

// Include the four-bit direction field and preserve the existing rounded steps.
static void testSteps() {
  const int16_t magnitude255[] = {0,255,128,64,31,15,8,3};
  const int16_t magnitude30[] = {0,30,15,8,4,2,1,1};
  const int16_t magnitude10[] = {0,10,5,3,1,1,1,1};
  for (unsigned raw = 0; raw < 16; ++raw) {
    int sign = (raw & 8) ? 1 : -1;
    check(knx_step_delta(raw,255) == sign*magnitude255[raw&7], "all DPT3 brightness codes");
    check(knx_step_delta(raw,30) == sign*magnitude30[raw&7], "all DPT3 hue codes");
    check(knx_step_delta(raw,10) == sign*magnitude10[raw&7], "all DPT3 effect codes");
    reset(); send(BRI_REL,{uint8_t(raw)});
    int expected = std::clamp(100 + sign*magnitude255[raw&7],0,255);
    check(bri == expected, "brightness callback for all DPT3 codes");
    if ((raw&7) == 0) expectStop("brightness STOP");
    else check(stateUpdates == 1 && publishes == 1, "brightness step publication");
  }
  for (Ga ga : {BRI_REL,R_REL,G_REL,B_REL,W_REL,WW_REL,CW_REL,H_REL,S_REL,V_REL,FX_REL}) {
    for (uint8_t stop : {uint8_t(DPT_3_007_DECREASE_STOP),uint8_t(DPT_3_007_INCREASE_STOP)}) {
      reset(); send(ga,{stop}); expectStop("single-channel STOP");
    }
  }
  for (unsigned mask = 0; mask < 16; ++mask) {
    uint8_t a=(mask&1)?8:0, b=(mask&2)?8:0, c=(mask&4)?8:0, d=(mask&8)?8:0;
    reset(); send(RGB_REL,{a,b,c}); expectStop("RGB composite STOP");
    reset(); send(HSV_REL,{a,b,c}); expectStop("HSV composite STOP");
    reset(); send(RGBW_REL,{a,b,c,d}); expectStop("RGBW composite STOP");
  }
}

// Exercise actual callbacks for absolute, relative, and mixed STOP/step colors.
static void testCommands() {
  reset(); send(HSV,{0,0,0}); expectColor(RGBW32(0,0,0,77),"HSV zero command");
  reset(); send(HSV,{85,255,255}); expectColor(RGBW32(0,255,0,77),"HSV green command");
  reset(); send(HSV,{170,255,255}); expectColor(RGBW32(0,0,255,77),"HSV blue command");
  reset(); send(HSV,{255,255,255}); expectColor(RGBW32(255,0,0,77),"HSV hue endpoint");
  reset(); send(HSV,{0,128,128}); expectColor(RGBW32(128,64,64,77),"HSV partial saturation/value");
  reset(RGBW32(128,0,0,77)); send(HUE,{85}); expectColor(RGBW32(0,128,0,77),"individual hue");
  reset(RGBW32(128,0,0,77)); send(SAT,{0}); expectColor(RGBW32(128,128,128,77),"individual saturation zero");
  reset(); send(VAL,{0}); expectColor(RGBW32(0,0,0,77),"individual value zero");
  reset(); send(RGB,{1,2,3}); expectColor(RGBW32(1,2,3,77),"RGB keeps white");
  reset(); send(RGBW,{1,2,3,4}); expectColor(RGBW32(1,2,3,4),"RGBW replaces white");
  reset(); send(RGBW,{1,2,3,4,0,0}); expectColor(RGBW32(1,2,3,4),"six-byte RGBW");
  reset(); send(RGB_REL,{8,15,7}); expectColor(RGBW32(120,83,37,77),"RGB mixed STOP/increase/decrease");
  reset(); send(RGBW_REL,{8,15,7,8}); expectColor(RGBW32(120,83,37,77),"RGBW white STOP");
  reset(); send(RGBW_REL,{8,0,8,15}); expectColor(RGBW32(120,80,40,80),"RGBW white step");
  reset(RGBW32(128,0,0,77)); send(HSV_REL,{8,7,15}); expectColor(RGBW32(131,2,2,77),"HSV mixed STOP/steps");
  reset(RGBW32(128,0,0,77)); send(H_REL,{9}); expectColor(RGBW32(128,64,0,77),"relative hue increase");
  reset(RGBW32(128,0,0,77)); send(H_REL,{1}); expectColor(RGBW32(128,0,64,77),"relative hue decrease wrap");
  reset(RGBW32(128,0,0,77)); send(S_REL,{1}); expectColor(RGBW32(128,128,128,77),"saturation lower clamp");
  reset(RGBW32(128,128,128,77)); send(S_REL,{9}); expectColor(RGBW32(128,0,0,77),"saturation upper clamp");
  reset(); send(V_REL,{1}); expectColor(RGBW32(0,0,0,77),"value lower clamp");
  reset(RGBW32(128,0,0,77)); send(V_REL,{9}); expectColor(RGBW32(255,0,0,77),"value upper clamp");
  reset(); send(R_REL,{9}); expectColor(RGBW32(255,80,40,77),"RGB upper clamp");
  reset(); send(R_REL,{1}); expectColor(RGBW32(0,80,40,77),"RGB lower clamp");
  reset(); send(W_REL,{15}); expectColor(RGBW32(120,80,40,80),"single white increase");
  reset(); send(W_REL,{7}); expectColor(RGBW32(120,80,40,74),"single white decrease");
  reset(); send(FX_REL,{9}); check(strip.getMainSegment().mode == 60,"effect increase");
  reset(); send(FX_REL,{1}); check(strip.getMainSegment().mode == 40,"effect decrease");
  reset(); send(WW_REL,{15}); expectColor(RGBW32(120,80,40,79),"warm white increase");
  reset(); send(CW_REL,{7}); expectColor(RGBW32(120,80,40,73),"cold white decrease");
}

// Brightness policy is shared by absolute RGB/HSV and HSV relative commands.
static void testAutoEnable(KnxIpUsermod& mod) {
  for (bool enabled : {false,true}) {
    mod.autoEnableOnColor = enabled; mod.autoEnableBrightness = 91;
    reset(RGBW32(0,0,0,77),0); send(HSV,{0,0,0});
    check(bri == 0,"black HSV must not auto-enable even with nonzero W");
    reset(RGBW32(0,0,0,77),0); send(HSV,{0,255,128});
    check(bri == (enabled?91:0),"HSV auto-enable setting");
    reset(RGBW32(0,0,0,77),0); send(RGB,{1,0,0});
    check(bri == (enabled?91:0),"RGB auto-enable setting");
    reset(RGBW32(128,0,0,77),0); send(V_REL,{15});
    check(bri == (enabled?91:0),"relative HSV auto-enable setting");
    reset(RGBW32(128,0,0,77),0); send(V_REL,{8});
    check(bri == 0 && publishes == 0,"STOP cannot auto-enable");
    reset(RGBW32(128,0,0,77),42); send(HSV,{85,255,255});
    check(bri == 42,"existing brightness unchanged");
  }
  mod.autoEnableOnColor = true;
  mod.autoEnableBrightness = 0;
  reset(RGBW32(0,0,0,77),0); send(HSV,{0,255,255});
  check(bri == 0,"zero configured auto-enable brightness");
  mod.autoEnableBrightness = 128;
}

// A stale/other-segment render cache must not replace the main segment's white.
static void testLiveColor() {
  for (unsigned main : {0u,1u}) {
    reset(); strip.main = main;
    strip.getMainSegment().colors[0] = RGBW32(128,0,0,77);
    Segment::renderedColor = RGBW32(0,255,0,9);
    send(HUE,{170}); expectColor(RGBW32(0,0,128,77),"HSV uses main segment, not render cache");
    reset(); strip.main = main;
    strip.getMainSegment().colors[0] = RGBW32(128,0,0,77);
    Segment::renderedColor = RGBW32(0,255,0,9);
    send(RGB,{1,2,3}); expectColor(RGBW32(1,2,3,77),"RGB preserves main white with stale cache");
  }
}

// Verify existing DPTs/directions and rejection of read/response/short payloads.
static void testRegistration() {
  check(KNX._gos.size() == 20 && KNX._callbacks.size() == 20,"all expected command objects");
  for (unsigned value = RGB; value <= RGBW_REL; ++value) {
    Ga ga = Ga(value);
    const auto& obj = KNX._gos.at(ga);
    DptMain expected = (ga == RGB || ga == HSV || ga == RGB_REL || ga == HSV_REL) ? DptMain::DPT_232xx :
      (ga == RGBW || ga == RGBW_REL) ? DptMain::DPT_251xx :
      (ga == HUE || ga == SAT || ga == VAL) ? DptMain::DPT_5xx : DptMain::DPT_3xx;
    check(obj.dpt == expected && obj.receive && !obj.transmit,"communication-object contract");
    for (KnxService svc : {KnxService::GroupValue_Read,KnxService::GroupValue_Response}) {
      reset(); send(ga,{9,9,9,9,0,0},svc); expectStop("non-write service ignored");
    }
    reset(); send(ga,{}); expectStop("empty payload ignored");
  }
  for (Ga ga : {RGB,HSV,RGB_REL,HSV_REL}) {
    reset(); send(ga,{255,255}); expectStop("short three-byte payload ignored");
  }
  for (Ga ga : {RGBW,RGBW_REL}) {
    reset(); send(ga,{255,255,255}); expectStop("short four-byte payload ignored");
  }
}

// Print reproducible before/after examples using the exact command implementation.
static void examples(KnxIpUsermod& mod) {
  for (const auto& payload : {std::array<uint8_t,3>{0,0,0}, {0,0,255}, {0,128,128}}) {
    reset(RGBW32(120,80,40,77),0); send(HSV,{payload[0],payload[1],payload[2]});
    uint32_t c=strip.getMainSegment().colors[0];
    std::printf("HSV [%u,%u,%u] -> RGBW [%u,%u,%u,%u], bri=%u\n",payload[0],payload[1],payload[2],R(c),G(c),B(c),W(c),bri);
  }
  for (uint8_t code : {uint8_t(0),uint8_t(8),uint8_t(15),uint8_t(7)}) {
    reset(); send(BRI_REL,{code});
    std::printf("brightness 100, DPT3 0x%02X -> %u, stateUpdated=%u, schedule=%u\n",code,bri,stateUpdates,publishes);
  }
  reset(); Segment::renderedColor=RGBW32(0,255,0,9); mod.applyHSV(0,1,1,true);
  std::printf("main W=77, render W=9 -> HSV output W=%u\n",W(strip.getMainSegment().colors[0]));
}

